        if formula[0] == 'AND':
            return all(is_formula(arg) for arg in formula[1:])
        elif formula[0] == 'OR':
            return any(is_formula(arg) for arg in formula[1:])
        elif formula[0] == 'NOT':
            return is_formula(formula[1])
        else:
